import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Values ascending (rearrangement inequality); equal values by original index.
        // Key = (value + 10^9) * 2^18 + index, since index < 2^18.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = (nextLong() + 1_000_000_000L) << 18 | i;
        Arrays.sort(key);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) out.append(' ');
            out.append((key[i] & ((1 << 18) - 1)) + 1);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// Values ascending (rearrangement inequality); equal values by original index.
	// Key = (value + 10^9) * 2^18 + index, since index < 2^18.
	key := make([]int64, n)
	for i := range key {
		key[i] = (nextInt()+1_000_000_000)<<18 | int64(i)
	}
	slices.Sort(key)
	out := make([]byte, 0, 7*n)
	for i, k := range key {
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, k&(1<<18-1)+1, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
